<?php
if(!defined('ABSPATH'))exit;
final class GRID_Cookie_Settings {
    public static function boot(){add_action('admin_init',array(__CLASS__,'register'));}
    public static function defaults(){return array('enabled'=>1,'group_menu'=>1,'reviewed'=>0,'functional'=>1,'logged_in'=>0,'days'=>180,'retention'=>180,'privacy'=>'','controller'=>get_bloginfo('name'),'contact'=>'','ga'=>'','clarity'=>'','services'=>array(),'position'=>'bottom-left','accent'=>'#672377','background'=>'#ffffff','text'=>'#29132f','radius'=>14,'font'=>'system','language'=>'auto','translations'=>array());}
    public static function get(){ $s=get_option(GRID_Cookie_Consent::OPTION,array());return array_merge(self::defaults(),is_array($s)?$s:array()); }
    public static function cookie_name(){ $path=wp_parse_url(home_url('/'),PHP_URL_PATH)?:'/';return (is_ssl()?($path==='/'?'__Host-':'__Secure-'):'').'grid_consent_'.substr(hash('sha256',home_url('/')),0,8); }
    public static function categories(){return array('functional','analytics','experience','marketing');}
    public static function register(){register_setting('grid_cookie',GRID_Cookie_Consent::OPTION,array('type'=>'array','sanitize_callback'=>array(__CLASS__,'sanitize')));}
    public static function contrast($a,$b){$l=function($hex){$v=array_map(function($v){$x=hexdec($v)/255;return $x<=.04045?$x/12.92:pow(($x+.055)/1.055,2.4);},str_split(ltrim($hex,'#'),2));return .2126*$v[0]+.7152*$v[1]+.0722*$v[2];};$x=$l($a);$y=$l($b);return(max($x,$y)+.05)/(min($x,$y)+.05);}
    public static function sanitize($in){
        $in=is_array($in)?$in:array();$s=self::defaults();foreach(array('enabled','group_menu','reviewed','functional','logged_in')as$k)$s[$k]=empty($in[$k])?0:1;
        foreach(array('controller','contact')as$k)$s[$k]=isset($in[$k])&&is_string($in[$k])?wp_html_excerpt(sanitize_text_field($in[$k]),240,''):'';
        $s['privacy']=isset($in['privacy'])&&is_string($in['privacy'])?esc_url_raw($in['privacy'],array('https','http')):'';
        $page=is_scalar($in['privacy_page']??null)?absint($in['privacy_page']):0;if($page&&get_post_type($page)==='page'&&get_post_status($page)==='publish')$s['privacy']=get_permalink($page);
        $s['ga']=isset($in['ga'])&&is_string($in['ga'])?strtoupper(trim($in['ga'])):'';if($s['ga']&&!preg_match('/^G-[A-Z0-9]{4,20}$/D',$s['ga'])){$s['ga']='';add_settings_error('grid_cookie','ga','Invalid GA4 measurement ID; the GA loader stays off.');}
        $s['clarity']=isset($in['clarity'])&&is_string($in['clarity'])?strtolower(trim($in['clarity'])):'';if($s['clarity']&&!preg_match('/^[a-z0-9]{4,32}$/D',$s['clarity'])){$s['clarity']='';add_settings_error('grid_cookie','clarity','Invalid Clarity project ID; the Clarity loader stays off.');}
        $s['days']=max(1,min(180,is_scalar($in['days']??null)?absint($in['days']):180));$s['retention']=max($s['days'],min(365,is_scalar($in['retention']??null)?absint($in['retention']):180));
        foreach(array('accent','background','text')as$k){$c=is_string($in[$k]??null)?sanitize_hex_color($in[$k]):null;$s[$k]=$c&&strlen($c)===7?$c:$s[$k];}
        if(self::contrast($s['accent'],'#ffffff')<4.5){$s['accent']='#672377';add_settings_error('grid_cookie','contrast','Button colour needs 4.5:1 contrast with white. A readable default was used.');}
        if(self::contrast($s['text'],$s['background'])<4.5){$s['text']='#29132f';$s['background']='#ffffff';add_settings_error('grid_cookie','textcontrast','Text/background colours need 4.5:1 contrast. Readable defaults were used.');}
        $s['radius']=max(0,min(24,is_scalar($in['radius']??null)?absint($in['radius']):14));$s['position']=in_array($in['position']??'',array('bottom-left','bottom-right','bottom-bar'),true)?$in['position']:'bottom-left';$s['font']=($in['font']??'')==='inherit'?'inherit':'system';
        $s['language']=preg_match('/^(auto|[a-z]{2,3}(?:-[A-Za-z0-9]{2,8})?)$/D',is_string($in['language']??null)?$in['language']:'')?$in['language']:'auto';
        $services=$in['services']??array();if(is_string($services))$services=json_decode($services,true);$seen=array();foreach(is_array($services)?array_slice($services,0,20):array()as$v){if(!is_array($v))continue;$id=is_string($v['id']??null)?sanitize_key($v['id']):'';$src=is_string($v['src']??null)?esc_url_raw($v['src'],array('https')):'';$u=wp_parse_url($src);$cat=$v['category']??'';if(!$id||isset($seen[$id])||!in_array($cat,self::categories(),true)||!$src||($u['scheme']??'')!=='https'||isset($u['user'])||isset($u['pass'])||empty($v['purpose'])||empty($v['provider'])){add_settings_error('grid_cookie','service','A custom service was rejected: use a unique ID, HTTPS script URL, provider, purpose and a valid category.');continue;}$seen[$id]=true;$row=array('id'=>$id,'src'=>$src,'category'=>$cat);foreach(array('name','provider','purpose')as$k)$row[$k]=is_string($v[$k]??null)?wp_html_excerpt(sanitize_text_field($v[$k]),500,''):$id;$row['cookies']=array();foreach((array)($v['cookies']??array())as$c)if(is_string($c)&&preg_match('/^[A-Za-z0-9_.-]{1,80}\*?$/D',$c))$row['cookies'][]=$c;$s['services'][]=$row;}
        // Scripts are a privileged site integration, including on multisite.
        if($s['services']&&!current_user_can('unfiltered_html')){$s['services']=self::get()['services'];add_settings_error('grid_cookie','scripts','Only an administrator with unfiltered_html may change custom executable services.');}
        $translations=$in['translations']??array();if(is_string($translations))$translations=json_decode($translations,true);foreach(is_array($translations)?array_slice($translations,0,30,true):array()as$lang=>$texts){if(!is_string($lang)||!preg_match('/^[a-z]{2,3}(?:-[A-Za-z0-9]{2,8})?$/D',$lang)||!is_array($texts))continue;foreach(array_keys(self::base_locales()['en'])as$key)if(isset($texts[$key])&&is_string($texts[$key]))$s['translations'][$lang][$key]=wp_html_excerpt(sanitize_textarea_field($texts[$key]),1200,'');}
        if(!$s['privacy']||!$s['controller']){$s['reviewed']=0;add_settings_error('grid_cookie','policy','Choose a policy URL and controller name. Optional services stay off until setup is reviewed.');}
        return $s;
    }
    public static function base_locales(){return array(
      'en'=>array('title'=>'Your privacy choices','notice'=>'We use necessary storage for this website and your consent choices. Optional services stay off until you choose. You can reject optional services and keep using the site, or change your choice at any time.','accept'=>'Accept all','reject'=>'Reject optional','manage'=>'Choose settings','save'=>'Save my choices','close'=>'Close','reopen'=>'Cookie settings','policy'=>'Cookie and privacy policy','necessary'=>'Necessary','necessaryInfo'=>'Always on: consent choices, security, sign-in and requested shopping-basket functions.','functional'=>'Functional cookies & external content','functionalNotice'=>'Functional cookies and external content support features such as videos, maps, translation and externally hosted fonts. If you decline, some features may be unavailable and the site may look different. Choose settings to enable these separately from statistics and session recording.','functionalInfo'=>'Optional: enable configured videos, maps, translation and externally hosted fonts. Without consent, these features stay off or may look different; ordinary website content remains available. External providers receive information such as your IP address and may use cookies or similar storage when their content loads. You can allow this category without allowing statistics or session recording.','analytics'=>'Audience statistics','analyticsInfo'=>'Allow Google Analytics and configured statistics services to measure website visits and interactions.','experience'=>'Session recording','experienceInfo'=>'Allow Microsoft Clarity to record interaction patterns and masked page views to help improve the site.','marketing'=>'Marketing','marketingInfo'=>'Allow the advertising services listed below. Google advertising and Clarity ad storage remain denied by this plugin.','withdraw'=>'Withdraw optional consent','pending'=>'Saving your choice…','error'=>'Optional services remain off because your choice could not be verified or saved. You can try again.','setup'=>'Optional services are disabled while this website completes its privacy setup.','gpc'=>'Your browser sends Global Privacy Control. All optional services stay off while that signal is enabled.','receipt'=>'Consent receipt','preview'=>'Preview only — no choices are stored and no services load.','blocked'=>'External content is blocked until you choose.','service'=>'Service','provider'=>'Provider','purpose'=>'Purpose','cookies'=>'Storage identifiers','duration'=>'Choices are remembered for up to %d days.','none'=>'No configured service in this category.'),
      'nb'=>array('title'=>'Dine personvernvalg','notice'=>'Vi bruker nødvendig lagring for nettstedet og samtykkevalgene dine. Valgfrie tjenester er av til du velger. Du kan avvise dem og fortsatt bruke nettstedet, eller endre valget når som helst.','accept'=>'Godta alle','reject'=>'Avvis valgfrie','manage'=>'Velg innstillinger','save'=>'Lagre mine valg','close'=>'Lukk','reopen'=>'Innstillinger for informasjonskapsler','policy'=>'Informasjonskapsler og personvern','necessary'=>'Nødvendige','necessaryInfo'=>'Alltid på: samtykkevalg, sikkerhet, innlogging og handlekurvfunksjoner du ber om.','functional'=>'Funksjonelle informasjonskapsler og eksternt innhold','functionalNotice'=>'Funksjonelle informasjonskapsler og eksternt innhold støtter blant annet videoer, kart, oversettelse og eksterne skrifttyper. Hvis du avviser, kan enkelte funksjoner være utilgjengelige og nettstedet se annerledes ut. Velg innstillinger for å tillate dette separat fra statistikk og øktopptak.','functionalInfo'=>'Valgfritt: aktiver konfigurerte videoer, kart, oversettelse og eksterne skrifttyper. Uten samtykke forblir disse funksjonene av eller kan se annerledes ut; vanlig innhold er fortsatt tilgjengelig. Eksterne leverandører mottar blant annet IP-adressen din og kan bruke informasjonskapsler eller lignende lagring når innholdet lastes. Du kan tillate denne kategorien uten å tillate statistikk eller øktopptak.','analytics'=>'Besøksstatistikk','analyticsInfo'=>'Tillat Google Analytics og konfigurerte statistikktjenester for å måle besøk og handlinger.','experience'=>'Øktopptak','experienceInfo'=>'Tillat Microsoft Clarity å registrere samhandlingsmønstre og maskerte sidevisninger for å forbedre nettstedet.','marketing'=>'Markedsføring','marketingInfo'=>'Tillat annonseringstjenestene som er oppført nedenfor. Programtillegget tillater ikke annonsebruk hos Google eller Clarity.','withdraw'=>'Trekk tilbake valgfritt samtykke','pending'=>'Lagrer valget ditt …','error'=>'Valgfrie tjenester er fortsatt av fordi valget ikke kunne bekreftes eller lagres. Du kan prøve igjen.','setup'=>'Valgfrie tjenester er av mens nettstedet fullfører personvernoppsettet.','gpc'=>'Nettleseren din sender Global Privacy Control. Alle valgfrie tjenester er av mens signalet er på.','receipt'=>'Samtykkekvittering','preview'=>'Kun forhåndsvisning — ingen valg lagres og ingen tjenester lastes.','blocked'=>'Eksternt innhold er blokkert til du velger.','service'=>'Tjeneste','provider'=>'Leverandør','purpose'=>'Formål','cookies'=>'Lagringsidentifikatorer','duration'=>'Valg huskes i opptil %d dager.','none'=>'Ingen konfigurert tjeneste i denne kategorien.')
    );}
    public static function locales(){$l=self::base_locales();foreach(self::get()['translations']as$k=>$v)$l[$k]=array_merge($l[$k]??$l['en'],$v);return $l;}
    public static function snapshot(){ $s=self::get();return array('controller'=>$s['controller'],'contact'=>$s['contact'],'privacy'=>$s['privacy'],'ga'=>$s['ga'],'clarity'=>$s['clarity'],'services'=>$s['services'],'functional'=>$s['functional'],'reviewed'=>$s['reviewed'],'days'=>$s['days'],'record_retention'=>$s['retention'],'locales'=>self::locales(),'policy_text'=>self::policy_text(),'policy_full_hash'=>self::policy_hash(),'mode'=>'strict-opt-in-no-advertising'); }
    public static function policy_hash(){ $s=self::get();$id=$s['privacy']?url_to_postid($s['privacy']):0;return $id?hash('sha256',(string)get_post_field('post_content',$id)):''; }
    public static function policy_text(){ $s=self::get();$id=$s['privacy']?url_to_postid($s['privacy']):0;return $id?wp_html_excerpt(wp_strip_all_tags((string)get_post_field('post_content',$id)),20000,''):''; }
    public static function revision(){return substr(hash('sha256',wp_json_encode(self::snapshot())),0,20);}
    public static function inventory(){ $s=self::get();$rows=array(array('name'=>'Consent choice','provider'=>$s['controller'],'category'=>'necessary','purpose'=>'Remember your choice and match a local consent receipt.','cookies'=>array(self::cookie_name()),'duration'=>$s['days'].' days'));
        if($s['ga'])$rows[]=array('name'=>'Google Analytics 4','provider'=>'Google','category'=>'analytics','purpose'=>'Audience statistics; Google signals and advertising personalisation disabled.','cookies'=>array('_ga','_ga_*'),'duration'=>'Up to '.$s['days'].' days (plugin configuration).');
        if($s['clarity'])$rows[]=array('name'=>'Microsoft Clarity','provider'=>'Microsoft','category'=>'experience','purpose'=>'Masked session recording and interaction patterns. Ad storage denied.','cookies'=>array('_clck','_clsk'),'duration'=>'Provider defaults: _clck up to 1 year; _clsk about 1 day. Verify your project settings.');
        if($s['functional'])$rows[]=array('name'=>'Functional cookies & external content','provider'=>'Providers embedded by this website (for example GTranslate/Google Fonts, YouTube, Vimeo or maps)','category'=>'functional','purpose'=>'Optional translation, typography and embedded content. Without consent, these features may be unavailable or the site may look different. Providers may use cookies or similar storage. Separate from statistics and session recording. The site owner must check which providers are used.','cookies'=>array(),'duration'=>'Provider-dependent; review each embedding before enabling.');
        foreach($s['services']as$v){$v['duration']='As declared by the service provider; verify before enabling.';$rows[]=$v;}return $rows;
    }
    public static function policy($raw=false){
        $s=self::get();$name=esc_html($s['controller']?:get_bloginfo('name'));$html='<section class="grid-cookie-policy"><h2>Cookies and optional services</h2><p>This notice describes the consent-controlled services configured for '.esc_html(home_url('/')).'. The controller is '.$name.'. Optional services do not load until you choose. Continuing to browse, scrolling, or closing a preferences window is not consent. You can reject optional services without losing access to ordinary website content.</p>';
        $html.='<p>Necessary storage supports your choice, security and functions you request, such as signing in or a shopping basket. Optional services use consent as the basis for device storage/access and associated consent-based processing. Where a requested service needs separate account, security or transaction processing, its own privacy notice also applies.</p><h3>Your choices</h3><p>Choose separate purposes below. Withdrawal stops future loading; it does not undo lawful processing already performed or automatically erase data previously received by a provider. We remove accessible first-party tracking cookies on withdrawal and reload to stop loaded runtimes. We cannot directly remove third-party or HttpOnly cookies.</p>[grid_cookie_settings]';
        if($s['functional'])$html.='<h3>Functional cookies and external content</h3><p>Optional external content can provide videos, maps, translation and externally hosted fonts. Without consent, some features may be unavailable and the website may look different; ordinary content remains available. External providers receive technical information such as your IP address and may use cookies or similar storage when content loads. You can allow this category separately from audience statistics and session recording in Cookie settings, and change your choice at any time.</p>';
        $html.='<h3>Configured service inventory</h3><p>This is a configuration-based declaration, not an automatic guarantee that every technology on the website has been discovered. The site owner must keep it current, including providers loaded through embedded content.</p><table><caption>Configured consent-controlled services</caption><thead><tr><th>Service / provider</th><th>Purpose</th><th>Storage / duration</th></tr></thead><tbody>';
        foreach(self::inventory()as$v)$html.='<tr><td>'.esc_html($v['name'].' — '.$v['provider']).'</td><td>'.esc_html($v['category'].': '.$v['purpose']).'</td><td>'.esc_html(implode(', ',$v['cookies']).'; '.$v['duration']).'</td></tr>';
        $html.='</tbody></table><h3>Information and recipients</h3><p>When you allow statistics or recording, the configured provider receives technical information such as browser/device details, page visits, interactions and network identifiers including your IP address. Clarity is configured to mask page text; sensitive pages/forms still need their own exclusion review. The plugin does not send your consent receipt ID, name or email to Google or Microsoft. Google Analytics and Clarity may involve processing outside Norway/EEA: the controller must assess the relevant vendor contracts, transfer safeguards and settings before enabling them.</p><p><a href="https://policies.google.com/privacy">Google privacy information</a> · <a href="https://privacy.microsoft.com/privacystatement">Microsoft privacy information</a>. External content providers have their own notices.</p>';
        $html.='<h3>Consent records and retention</h3><p>Your choice is stored in a necessary first-party cookie (and, where needed, a browser-local cross-tab synchronisation entry) for up to '.(int)$s['days'].' days. This website stores local consent receipts for up to '.(int)$s['retention'].' days, identifying a decision with a random receipt ID, time, purposes, policy revision and language. The plugin does not store your IP address, user agent, account identity or browsing URL in that receipt. Hosting/security logs are separate and need their own retention notice. Changes to purposes/services prompt a fresh choice. No cross-site consent sharing is used. Global Privacy Control keeps all optional services off worldwide.</p><h3>Your rights and contact</h3><p>Where applicable, you can request access, correction, erasure, restriction or portability of personal data, object to relevant processing, and complain to the competent supervisory authority. In Norway this is <a href="https://www.datatilsynet.no/">Datatilsynet</a>. You can withdraw optional consent using Cookie settings at any time. Some rights depend on the purpose and legal basis; provide your receipt ID if asking about a consent record.</p>';
        $html.='<p>Controller contact: '.esc_html($s['contact']?:'[Site owner: add the privacy contact before publishing this draft.]').'</p><p>This notice does not replace information about newsletter, contact-form, account, payment, employment or other processing outside the configured consent services. The controller must add those disclosures where relevant.</p></section>';
        return $raw===true?$html:do_shortcode($html);
    }
}
